import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators, AbstractControl, ValidationErrors } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../../../../services/auth.service';

@Component({
  selector: 'app-register',
  templateUrl: './register.component.html',
  styleUrls: ['./register.component.css']
})
export class RegisterComponent implements OnInit {
  registerForm!: FormGroup;
  loading = false;
  submitted = false;
  errorMessage: string = '';

  constructor(
    private formBuilder: FormBuilder,
    private authService: AuthService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.initializeForm();

    // Si ya está autenticado, redirigir al dashboard
    if (this.authService.isAuthenticated()) {
      this.router.navigate(['/dashboard']);
    }
  }

  initializeForm(): void {
    this.registerForm = this.formBuilder.group({
      name: ['', [Validators.required, Validators.minLength(3)]],
      email: ['', [Validators.required, Validators.email]],
      password: ['', [Validators.required, Validators.minLength(8), this.passwordStrength]],
      confirmPassword: ['', Validators.required]
    }, { validators: this.passwordMatchValidator });
  }

  /**
   * Validador de fortaleza de contraseña
   */
  passwordStrength(control: AbstractControl): ValidationErrors | null {
    const value = control.value;

    if (!value) {
      return null;
    }

    const hasUpperCase = /[A-Z]/.test(value);
    const hasLowerCase = /[a-z]/.test(value);
    const hasNumeric = /[0-9]/.test(value);
    const hasSpecialChar = /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(value);

    const passwordValid = hasUpperCase && hasLowerCase && hasNumeric;

    if (!passwordValid) {
      return {
        passwordStrength: {
          hasUpperCase,
          hasLowerCase,
          hasNumeric,
          hasSpecialChar
        }
      };
    }

    return null;
  }

  /**
   * Validador de coincidencia de contraseñas
   */
  passwordMatchValidator(control: AbstractControl): ValidationErrors | null {
    const password = control.get('password');
    const confirmPassword = control.get('confirmPassword');

    if (!password || !confirmPassword) {
      return null;
    }

    return password.value === confirmPassword.value ? null : { passwordMismatch: true };
  }

  get f() {
    return this.registerForm.controls;
  }

  getPasswordStrengthMessage(): string {
    const password = this.f['password'];

    if (!password.errors || !password.errors['passwordStrength']) {
      return 'La contraseña es fuerte';
    }

    const errors = password.errors['passwordStrength'];
    const missing: string[] = [];

    if (!errors.hasUpperCase) missing.push('mayúscula');
    if (!errors.hasLowerCase) missing.push('minúscula');
    if (!errors.hasNumeric) missing.push('número');

    return `Falta: ${missing.join(', ')}`;
  }

  onSubmit(): void {
    this.submitted = true;
    this.errorMessage = '';

    if (this.registerForm.invalid) {
      return;
    }

    this.loading = true;
    this.authService.register(this.registerForm.value).subscribe({
      next: () => {
        this.loading = false;
        this.router.navigate(['/dashboard']);
      },
      error: (error: any) => {
        this.loading = false;
        this.errorMessage = error.message;
      }
    });
  }

  goToLogin(): void {
    this.router.navigate(['/login']);
  }

  // Helpers para evaluar requisitos de contraseña desde el template
  // (los templates de Angular no permiten regex literales)
  hasMinLength(): boolean {
    const v = this.f['password'].value;
    return !!v && v.length >= 8;
  }

  hasUpperCase(): boolean {
    const v = this.f['password'].value;
    return !!v && /[A-Z]/.test(v);
  }

  hasLowerCase(): boolean {
    const v = this.f['password'].value;
    return !!v && /[a-z]/.test(v);
  }

  hasNumber(): boolean {
    const v = this.f['password'].value;
    return !!v && /[0-9]/.test(v);
  }
}
<div class="register-container">
  <div class="register-card">
    <h1>Crear Cuenta</h1>
    
    <!-- Mensaje de error -->
    <div *ngIf="errorMessage" class="alert alert-error">
      {{ errorMessage }}
    </div>

    <!-- Formulario de registro -->
    <form [formGroup]="registerForm" (ngSubmit)="onSubmit()">
      <!-- Campo Nombre -->
      <div class="form-group">
        <label for="name">Nombre Completo:</label>
        <input
          type="text"
          id="name"
          class="form-control"
          [class.is-invalid]="submitted && f['name'].errors"
          formControlName="name"
          placeholder="Tu nombre completo"
        />
        <div *ngIf="submitted && f['name'].errors" class="invalid-feedback">
          <span *ngIf="f['name'].errors['required']">El nombre es requerido</span>
          <span *ngIf="f['name'].errors['minlength']">
            El nombre debe tener al menos {{ f['name'].errors['minlength'].requiredLength }} caracteres
          </span>
        </div>
      </div>

      <!-- Campo Email -->
      <div class="form-group">
        <label for="email">Email:</label>
        <input
          type="email"
          id="email"
          class="form-control"
          [class.is-invalid]="submitted && f['email'].errors"
          formControlName="email"
          placeholder="correo@ejemplo.com"
        />
        <div *ngIf="submitted && f['email'].errors" class="invalid-feedback">
          <span *ngIf="f['email'].errors['required']">El email es requerido</span>
          <span *ngIf="f['email'].errors['email']">El email no es válido</span>
        </div>
      </div>

      <!-- Campo Contraseña -->
      <div class="form-group">
        <label for="password">Contraseña:</label>
        <input
          type="password"
          id="password"
          class="form-control"
          [class.is-invalid]="submitted && f['password'].errors"
          formControlName="password"
          placeholder="Mínimo 8 caracteres"
        />
        <div class="password-strength" *ngIf="f['password'].value && submitted">
          <span [class.strength-weak]="f['password'].errors?.['passwordStrength']"
                [class.strength-strong]="!f['password'].errors?.['passwordStrength']">
            {{ getPasswordStrengthMessage() }}
          </span>
        </div>
        <div *ngIf="submitted && f['password'].errors" class="invalid-feedback">
          <span *ngIf="f['password'].errors['required']">La contraseña es requerida</span>
          <span *ngIf="f['password'].errors['minlength']">
            La contraseña debe tener al menos {{ f['password'].errors['minlength'].requiredLength }} caracteres
          </span>
          <span *ngIf="f['password'].errors['passwordStrength']">
            {{ getPasswordStrengthMessage() }}
          </span>
        </div>
      </div>

      <!-- Campo Confirmar Contraseña -->
      <div class="form-group">
        <label for="confirmPassword">Confirmar Contraseña:</label>
        <input
          type="password"
          id="confirmPassword"
          class="form-control"
          [class.is-invalid]="submitted && (f['confirmPassword'].errors || registerForm.errors?.['passwordMismatch'])"
          formControlName="confirmPassword"
          placeholder="Repite tu contraseña"
        />
        <div *ngIf="submitted && (f['confirmPassword'].errors || registerForm.errors?.['passwordMismatch'])" class="invalid-feedback">
          <span *ngIf="f['confirmPassword'].errors?.['required']">Este campo es requerido</span>
          <span *ngIf="registerForm.errors?.['passwordMismatch']">Las contraseñas no coinciden</span>
        </div>
      </div>

      <!-- Requisitos de contraseña -->
      <div class="password-requirements">
        <p>La contraseña debe contener:</p>
        <ul>
          <li [class.met]="hasMinLength()">
            ✓ Mínimo 8 caracteres
          </li>
          <li [class.met]="hasUpperCase()">
            ✓ Al menos una mayúscula
          </li>
          <li [class.met]="hasLowerCase()">
            ✓ Al menos una minúscula
          </li>
          <li [class.met]="hasNumber()">
            ✓ Al menos un número
          </li>
        </ul>
      </div>

      <!-- Botones -->
      <div class="form-actions">
        <button 
          type="submit" 
          class="btn btn-primary"
          [disabled]="loading"
        >
          <span *ngIf="!loading">Registrarse</span>
          <span *ngIf="loading">
            <span class="spinner-border"></span> Registrando...
          </span>
        </button>
      </div>

      <!-- Enlace a login -->
      <div class="form-links">
        <p>¿Ya tienes cuenta? 
          <button 
            type="button" 
            class="link-button"
            (click)="goToLogin()"
          >
            Inicia sesión aquí
          </button>
        </p>
      </div>
    </form>
  </div>
</div>
